import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily } = loadFont();



export type SpotifyAnimationProps = Record<string, any>;

// Sub-component for individual animated text lines
const AnimatedText: React.FC<{ text: string; delay: number; accentColor: string }> = ({ text, delay, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const progress = spring({ frame: frame - delay, fps, config: { damping: 14 } });
  
  const opacity = interpolate(progress, [0, 1], [0, 1]);
  const translateY = interpolate(progress, [0, 1], [40, 0]);

  return (
    <div
      style={{
        opacity,
        transform: `translateY(${translateY}px)`,
        color: accentColor,
        fontSize: "52px",
        fontWeight: 800,
        textAlign: "center",
        width: "90%",
        lineHeight: 1.2,
        letterSpacing: "-1.5px",
        transition: "none",
        fontFamily,
      }}
    >
      {text}
    </div>
  );
};

// Sub-component for equalizer bars representing "listening data"
const EqBars: React.FC<{ startFrame: number; accentColor: string }> = ({ startFrame, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const activeFrame = Math.max(0, frame - startFrame);
  const inProgress = spring({ frame: activeFrame, fps, config: { damping: 12 } });

  return (
    <div style={{ display: "flex", gap: "12px", alignItems: "center", height: "100px", transition: "none" }}>
      {[1, 2, 3].map((i) => {
        const wave = (Math.sin(activeFrame / 6 + i * 1.5) + 1) / 2;
        const h = inProgress * (24 + wave * 64);
        return (
          <div
            key={i}
            style={{
              width: "16px",
              height: `${h}px`,
              backgroundColor: accentColor,
              borderRadius: "8px",
              transition: "none",
            }}
          />
        );
      })}
    </div>
  );
};

// Sub-component for the "story" cards
const StoryCard: React.FC<{ style?: React.CSSProperties; accentColor: string; children?: React.ReactNode }> = ({ style, accentColor, children }) => (
  <div
    style={{
      position: "absolute",
      width: "440px",
      height: "760px",
      left: "50%",
      top: "50%",
      marginLeft: "-220px",
      marginTop: "-380px",
      border: `4px solid ${accentColor}`,
      borderRadius: "32px",
      overflow: "hidden",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      boxShadow: "0 24px 48px rgba(0,0,0,0.2)",
      transition: "none",
      ...style,
    }}
  >
    {/* Semi-transparent background layer */}
    <div style={{ position: "absolute", width: "100%", height: "100%", backgroundColor: accentColor, opacity: 0.1, transition: "none" }} />
    
    {/* Content layer */}
    <div style={{ position: "relative", zIndex: 1, width: "100%", height: "100%", display: "flex", flexDirection: "column", alignItems: "center" }}>
      {children}
    </div>
  </div>
);

// Sub-component for share nodes fanning out
const ShareNodes: React.FC<{ startFrame: number; accentColor: string }> = ({ startFrame, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const s4Progress = spring({ frame: frame - startFrame, fps, config: { damping: 12 } });

  return (
    <>
      {[0, 1, 2, 3, 4, 5].map((i) => {
        const angle = (i * Math.PI * 2) / 6;
        const distance = interpolate(s4Progress, [0, 1], [0, 480]);
        const x = Math.cos(angle) * distance;
        const y = Math.sin(angle) * distance;
        const scale = interpolate(s4Progress, [0, 0.7, 1], [0, 1.2, 1]);
        const opacity = interpolate(s4Progress, [0, 0.2, 0.8, 1], [0, 1, 1, 0]);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: "-24px",
              top: "-24px",
              width: "48px",
              height: "48px",
              borderRadius: "24px",
              backgroundColor: accentColor,
              transform: `translateX(${x}px) translateY(${y}px) scale(${scale})`,
              opacity,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: "0 8px 16px rgba(0,0,0,0.2)",
              transition: "none",
            }}
          >
            <div style={{ width: "16px", height: "16px", borderRadius: "8px", backgroundColor: "#000", opacity: 0.3 }} />
          </div>
        );
      })}
    </>
  );
};

const SpotifyAnimation: React.FC<SpotifyAnimationProps> = ({
  backgroundColor = "#aa00e6",
  transparentBackground = false,
  durationInSeconds = 12,
  spotifyIconUrl = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/44535a02c8d3423f82cbfc7fe95c8b71.png",
  textPart1 = "Every end of the year,",
  textPart2 = "Spotify turns your listening data",
  textPart3 = "into a story",
  textPart4 = "that people can distribute and post anywhere.",
  accentColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timeline orchestration based on dynamic duration
  const durationFrames = durationInSeconds * fps;
  const s1Start = 0;
  const s2Start = Math.floor(durationFrames * 0.15);
  const s3Start = Math.floor(durationFrames * 0.40);
  const s4Start = Math.floor(durationFrames * 0.65);

  // Global visual progress metrics
  const s2Progress = spring({ frame: frame - s2Start, fps, config: { damping: 14 } });
  const s3Progress = spring({ frame: frame - s3Start, fps, config: { damping: 14 } });
  const s4Progress = spring({ frame: frame - s4Start, fps, config: { damping: 14 } });

  // Floating animation for the center container to keep it energetic
  const centerFloatY = Math.sin(frame / 20) * 12;

  // Logo transformations (Morphs from center focus to card header)
  const logoScale = s2Progress * interpolate(s3Progress, [0, 1], [1, 0.55]);
  const logoY = interpolate(s3Progress, [0, 1], [0, -230]);
  
  // EQ bars fade out as card scales up
  const eqOpacity = interpolate(s3Progress, [0, 0.5], [1, 0]);

  // Card fan out logic (Scene 4)
  const leftCardRot = interpolate(s4Progress, [0, 1], [0, -12]);
  const leftCardX = interpolate(s4Progress, [0, 1], [0, -210]);
  const leftCardY = interpolate(s4Progress, [0, 1], [0, 40]);

  const rightCardRot = interpolate(s4Progress, [0, 1], [0, 12]);
  const rightCardX = interpolate(s4Progress, [0, 1], [0, 210]);
  const rightCardY = interpolate(s4Progress, [0, 1], [0, 40]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily }}>
      
      {/* Top Text Safe Zone */}
      <div style={{ position: "absolute", top: height * 0.12, width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: "20px" }}>
        <AnimatedText text={textPart1} delay={s1Start} accentColor={accentColor} />
        <AnimatedText text={textPart2} delay={s2Start} accentColor={accentColor} />
      </div>

      {/* Center Visuals Container */}
      <div style={{ position: "absolute", left: width / 2, top: height / 2, transform: `translateY(${centerFloatY}px)`, transition: "none" }}>
        
        {/* Background Share Nodes (bursts at Scene 4) */}
        <ShareNodes startFrame={s4Start} accentColor={accentColor} />

        {/* Left Fanned Card */}
        <StoryCard style={{ transform: `scale(${s3Progress}) translateX(${leftCardX}px) translateY(${leftCardY}px) rotate(${leftCardRot}deg)`, opacity: s3Progress }} accentColor={accentColor} />
        
        {/* Right Fanned Card */}
        <StoryCard style={{ transform: `scale(${s3Progress}) translateX(${rightCardX}px) translateY(${rightCardY}px) rotate(${rightCardRot}deg)`, opacity: s3Progress }} accentColor={accentColor} />
        
        {/* Main Center Card */}
        <StoryCard style={{ transform: `scale(${s3Progress})`, opacity: s3Progress }} accentColor={accentColor}>
          {/* Card Header UI line */}
          <div style={{ width: "85%", height: "6px", backgroundColor: accentColor, opacity: 0.3, borderRadius: "3px", marginTop: "40px", position: "relative" }}>
            <div style={{ width: "40%", height: "100%", backgroundColor: accentColor, borderRadius: "3px" }} />
          </div>
          
          {/* Abstract Data Visualization inside the card */}
          <div style={{ position: "absolute", top: "240px", width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: "28px", opacity: s3Progress }}>
            {[0.8, 0.95, 0.6, 0.85, 0.5].map((w, i) => (
              <div
                key={i}
                style={{
                  width: `${w * 75}%`,
                  height: "24px",
                  backgroundColor: accentColor,
                  opacity: 0.2 + (i * 0.15),
                  borderRadius: "12px",
                  transition: "none",
                }}
              />
            ))}
          </div>
        </StoryCard>

        {/* Left Equalizer */}
        <div style={{ opacity: eqOpacity, position: "absolute", left: "-260px", top: "-50px", transition: "none" }}>
          <EqBars startFrame={s2Start} accentColor={accentColor} />
        </div>

        {/* Right Equalizer */}
        <div style={{ opacity: eqOpacity, position: "absolute", left: "180px", top: "-50px", transition: "none" }}>
          <EqBars startFrame={s2Start} accentColor={accentColor} />
        </div>

        {/* Spotify Icon (Morphs and acts as the anchor) */}
        <Img
          src={spotifyIconUrl}
          style={{
            width: "180px",
            height: "180px",
            position: "absolute",
            left: "-90px",
            top: "-90px",
            transform: `scale(${logoScale}) translateY(${logoY}px)`,
            opacity: s2Progress,
            transition: "none",
          }}
        />
      </div>

      {/* Bottom Text Safe Zone */}
      <div style={{ position: "absolute", bottom: height * 0.12, width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: "20px" }}>
        <AnimatedText text={textPart3} delay={s3Start} accentColor={accentColor} />
        <AnimatedText text={textPart4} delay={s4Start} accentColor={accentColor} />
      </div>

    </AbsoluteFill>
  );
};

export default SpotifyAnimation;